<?php
declare(strict_types=1);
require_once __DIR__.'/finance_core.php';require_once __DIR__.'/document_storage.php';
function financeArchive(PDO $pdo,string $bytes,string $name,?int $mailAttachment=null):int {
 if(strlen($bytes)<1||strlen($bytes)>10*1024*1024)throw new InvalidArgumentException('Belegoriginal 1 Byte bis 10 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->buffer($bytes);if(!in_array($mime,['application/pdf','image/jpeg','image/png','image/webp','text/plain'],true))throw new InvalidArgumentException('Belegformat nicht erlaubt.');if($mime==='application/pdf'&&!str_starts_with($bytes,'%PDF-'))throw new InvalidArgumentException('PDF-Kopf fehlt.');if(str_starts_with($mime,'image/')){$size=@getimagesizefromstring($bytes);if(!$size||$size[0]>12000||$size[1]>12000)throw new InvalidArgumentException('Bildabmessungen ungültig.');}$hash=hash('sha256',$bytes);
 $pdo->beginTransaction();try{$pdo->query('SELECT id FROM app_mutex WHERE id=1 FOR UPDATE')->fetch();if($mailAttachment){$q=$pdo->prepare('SELECT id FROM finance_receipts WHERE mail_attachment_id=?');$q->execute([$mailAttachment]);if($id=$q->fetchColumn()){$pdo->commit();return (int)$id;}}
  $q=$pdo->prepare('SELECT * FROM documents WHERE sha256=? ORDER BY id LIMIT 1');$q->execute([$hash]);$doc=$q->fetch();
  if(!$doc){$stored=bin2hex(random_bytes(16));$path=documentStorageDir().'/'.$stored;$f=fopen($path,'x');if(!$f)throw new RuntimeException('Belegspeicher nicht verfügbar.');try{if(fwrite($f,$bytes)!==strlen($bytes))throw new RuntimeException('Datei unvollständig.');}finally{fclose($f);}@chmod($path,0600);$pdo->prepare('INSERT INTO documents(category,title,original_name,stored_name,mime_type,size_bytes,sha256) VALUES(?,?,?,?,?,?,?)')->execute(['invoice','Belegoriginal',gszName($name),$stored,$mime,strlen($bytes),$hash]);$docId=(int)$pdo->lastInsertId();}
  else{$docId=(int)$doc['id'];if(!preg_match('/^[a-f0-9]{32}$/D',$doc['stored_name'])||!is_file(documentStorageDir().'/'.$doc['stored_name'])||hash_file('sha256',documentStorageDir().'/'.$doc['stored_name'])!==$hash)throw new RuntimeException('Vorhandenes Original beschädigt.');}
  $q=$pdo->prepare('SELECT id FROM finance_receipts WHERE document_id=? ORDER BY id DESC LIMIT 1');$q->execute([$docId]);$id=$q->fetchColumn();if(!$id){$pdo->prepare('INSERT INTO finance_receipts(document_id,mail_attachment_id) VALUES(?,?)')->execute([$docId,$mailAttachment]);$id=(int)$pdo->lastInsertId();}gszAudit($pdo,$_SESSION['admin_id']??null,'receipt_original',['receipt_id'=>(int)$id,'document_id'=>$docId,'sha256'=>$hash]);$pdo->commit();return (int)$id;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeReceiptFields(array $in):array {
 $merchant=trim((string)($in['merchant']??''));$date=(string)($in['receipt_date']??'');$direction=(string)($in['direction']??'expense');$category=trim((string)($in['category']??''));$method=trim((string)($in['payment_method']??''));if($merchant===''||mb_strlen($merchant)>190||!zgsValidDate($date)||!in_array($direction,['expense','income'],true)||$category===''||mb_strlen($category)>100||mb_strlen($method)>40)throw new InvalidArgumentException('Händler, Datum, Richtung, Kategorie und Zahlungsart prüfen.');$gross=financeCents((string)($in['gross']??''),'de');$rate=filter_var($in['tax_rate']??'',FILTER_VALIDATE_INT);if($gross<=0||!in_array($rate,[0,7,19],true))throw new InvalidArgumentException('Positiver Bruttobetrag und einheitlicher Satz 0/7/19 erforderlich. Sonderfälle fachlich prüfen.');$tax=($in['tax']??'')!==''?financeCents((string)$in['tax'],'de'):financeTax($gross,$rate);$net=($in['net']??'')!==''?financeCents((string)$in['net'],'de'):$gross-$tax;if($tax<0||$net<0||$gross!==$net+$tax||abs($tax-financeTax($gross,$rate))>1)throw new InvalidArgumentException('Netto + USt muss Brutto entsprechen; Steuerabweichung fachlich prüfen.');return [$merchant,$date,$direction,$gross,$net,$tax,$rate,$category,$method];
}
function financeSaveReceipt(PDO $pdo,int $admin,int $id,array $input,bool $confirm):void {
 $fields=financeReceiptFields($input);$pid=(int)($input['property_id']??0);if($pid){$q=$pdo->prepare('SELECT id FROM properties WHERE id=?');$q->execute([$pid]);if(!$q->fetchColumn())throw new InvalidArgumentException('Objekt unbekannt.');}
 $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM finance_receipts WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch();if(!$old||$old['status']!=='draft')throw new RuntimeException('Bestätigter Beleg gesperrt. Korrekturentwurf statt Überschreiben.');if(isset($input['version'])&&(int)$input['version']!==(int)$old['version'])throw new RuntimeException('Entwurf inzwischen geändert. Neu laden.');$pdo->prepare('UPDATE finance_receipts SET merchant=?,receipt_date=?,direction=?,gross_cents=?,net_cents=?,tax_cents=?,tax_rate=?,category=?,payment_method=?,property_id=?,version=version+1 WHERE id=?')->execute([...$fields,$pid?:null,$id]);
 if($confirm){$year=(int)substr($fields[1],0,4);$pdo->prepare('INSERT INTO receipt_sequences(year,last_number) VALUES(?,0) ON DUPLICATE KEY UPDATE year=VALUES(year)')->execute([$year]);$q=$pdo->prepare('SELECT last_number FROM receipt_sequences WHERE year=? FOR UPDATE');$q->execute([$year]);$next=(int)$q->fetchColumn()+1;$pdo->prepare('UPDATE receipt_sequences SET last_number=? WHERE year=?')->execute([$next,$year]);$pdo->prepare("UPDATE finance_receipts SET number=?,status='confirmed' WHERE id=?")->execute([sprintf('B-%04d-%05d',$year,$next),$id]);}
 if($confirm&&$old['predecessor_id'])$pdo->prepare("UPDATE finance_receipts SET status='corrected' WHERE id=?")->execute([$old['predecessor_id']]);
 gszAudit($pdo,$admin,$confirm?'receipt_confirmed':'receipt_draft_saved',['receipt_id'=>$id,'previous_version'=>(int)$old['version']]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeCandidates(PDO $pdo):array {
 $out=[];$receipts=$pdo->query("SELECT r.*,COALESCE(p.amount,0) paid FROM finance_receipts r LEFT JOIN (SELECT receipt_id,SUM(amount_cents) amount FROM finance_payments GROUP BY receipt_id) p ON p.receipt_id=r.id WHERE r.status='confirmed' LIMIT 1000")->fetchAll();foreach($receipts as $r)$out[]=['kind'=>'receipt','id'=>(int)$r['id'],'name'=>$r['merchant'],'date'=>$r['receipt_date'],'remaining_cents'=>($r['direction']==='expense'?-1:1)*(int)$r['gross_cents']-(int)$r['paid']];
 $invoices=$pdo->query("SELECT i.*,COALESCE(p.amount,0) paid FROM invoices i LEFT JOIN (SELECT invoice_id,SUM(amount_cents) amount FROM finance_payments GROUP BY invoice_id) p ON p.invoice_id=i.id WHERE i.status IN ('issued','paid') AND i.document_kind='invoice' LIMIT 1000")->fetchAll();foreach($invoices as $i)$out[]=['kind'=>'invoice','id'=>(int)$i['id'],'name'=>$i['recipient_name'],'date'=>$i['invoice_date'],'remaining_cents'=>financeCents($i['gross_total'])-(int)$i['paid']];return $out;
}
function financePay(PDO $pdo,int $admin,string $kind,int $id,int $amount,string $date,string $request,?int $bank=null):int {
 if(!in_array($kind,['receipt','invoice'],true)||!zgsValidDate($date)||$amount===0||abs($amount)>99999999999||!preg_match('/^[a-f0-9]{64}$/D',$request))throw new InvalidArgumentException('Zahlungsangaben ungültig.');$pdo->beginTransaction();try{
 $q=$pdo->prepare('SELECT * FROM finance_payments WHERE request_key=?');$q->execute([$request]);if($old=$q->fetch()){if((int)($old[$kind.'_id']??0)!==$id||(int)$old['amount_cents']!==$amount||$old['paid_on']!==$date||(int)($old['bank_transaction_id']??0)!==(int)($bank??0))throw new RuntimeException('Anfrageidentität mit abweichenden Daten.');$pdo->commit();return (int)$old['id'];}
 $table=$kind==='receipt'?'finance_receipts':'invoices';$q=$pdo->prepare('SELECT * FROM '.$table.' WHERE id=? FOR UPDATE');$q->execute([$id]);$entity=$q->fetch();if(!$entity)throw new RuntimeException('Beleg/Rechnung unbekannt.');
 if($kind==='receipt'){if($entity['status']!=='confirmed')throw new RuntimeException('Beleg zuerst prüfen und bestätigen.');$sign=$entity['direction']==='expense'?-1:1;$gross=(int)$entity['gross_cents'];$tax=(int)$entity['tax_cents'];}
 else{if(($entity['document_kind']??'invoice')!=='invoice')throw new RuntimeException('Zahlung gehört zur Ursprungsrechnung, nicht zu Angebot/Stornobeleg.');if(!in_array($entity['status'],['issued','paid'],true)&&!($entity['status']==='cancelled'&&!empty($entity['correction_document_id'])&&$amount<0))throw new RuntimeException('Nur ausgestellte Rechnungen oder bestätigte Erstattung nach Stornobeleg.');$q=$pdo->prepare('SELECT COUNT(DISTINCT tax_rate) FROM invoice_items WHERE invoice_id=?');$q->execute([$id]);if((int)$q->fetchColumn()>1)throw new RuntimeException('Gemischte Steuersätze: Teilzahlung benötigt manuelle Fachprüfung.');$sign=1;$gross=financeCents($entity['gross_total']);$tax=financeCents($entity['tax_total']);}
 if($gross<=0)throw new RuntimeException('Positiver Gesamtbetrag erforderlich.');$q=$pdo->prepare('SELECT amount_cents,tax_cents FROM finance_payments WHERE '.$kind.'_id=? FOR UPDATE');$q->execute([$id]);$paymentRows=$q->fetchAll();$paid=['amount'=>array_sum(array_column($paymentRows,'amount_cents')),'tax'=>array_sum(array_column($paymentRows,'tax_cents'))];$newTotal=(int)$paid['amount']+$amount;if($newTotal*$sign<0||$newTotal*$sign>$gross)throw new RuntimeException('Zahlung/Erstattung überschreitet offenen oder bereits gezahlten Betrag.');
 if($bank){$q=$pdo->prepare('SELECT * FROM bank_transactions WHERE id=? FOR UPDATE');$q->execute([$bank]);$bt=$q->fetch();if(!$bt||(int)$bt['amount_cents']!==$amount||$bt['booked_on']!==$date)throw new RuntimeException('Bankbetrag/-datum muss exakt passen. Aufteilung eines Umsatzes noch nicht unterstützt.');$q=$pdo->prepare('SELECT id FROM finance_payments WHERE allocation_key=?');$q->execute([$bank]);if($q->fetchColumn())throw new RuntimeException('Bankumsatz bereits zugeordnet.');}
 $newTax=$sign*intdiv(abs($newTotal)*$tax+intdiv($gross,2),$gross);$deltaTax=$newTax-(int)$paid['tax'];$pdo->prepare('INSERT INTO finance_payments(receipt_id,invoice_id,bank_transaction_id,allocation_key,paid_on,amount_cents,tax_cents,request_key,admin_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$kind==='receipt'?$id:null,$kind==='invoice'?$id:null,$bank,$bank,$date,$amount,$deltaTax,$request,$admin]);$payment=(int)$pdo->lastInsertId();
 if($kind==='invoice'&&$entity['status']!=='cancelled')$pdo->prepare('UPDATE invoices SET status=?,paid_at=IF(?=1,UTC_TIMESTAMP(),NULL) WHERE id=?')->execute([$newTotal===$gross?'paid':'issued',$newTotal===$gross?1:0,$id]);gszAudit($pdo,$admin,'payment_confirmed',['payment_id'=>$payment,'kind'=>$kind,'entity_id'=>$id,'bank_id'=>$bank]);$pdo->commit();return $payment;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeReverse(PDO $pdo,int $admin,int $id,string $reason):void {
 $reason=trim($reason);if($reason===''||mb_strlen($reason)>500)throw new InvalidArgumentException('Korrekturgrund 1–500 Zeichen.');$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM finance_payments WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch();if(!$old||$old['reversal_of'])throw new RuntimeException('Ursprungszahlung erforderlich.');$q=$pdo->prepare('SELECT id FROM finance_payments WHERE reversal_of=?');$q->execute([$id]);if($q->fetchColumn()){$pdo->commit();return;}
 $kind=$old['receipt_id']?'receipt':'invoice';$entity=(int)($old['receipt_id']?:$old['invoice_id']);$table=$kind==='receipt'?'finance_receipts':'invoices';$q=$pdo->prepare('SELECT * FROM '.$table.' WHERE id=? FOR UPDATE');$q->execute([$entity]);$entityRow=$q->fetch();
 $q=$pdo->prepare('SELECT amount_cents FROM finance_payments WHERE '.$kind.'_id=? FOR UPDATE');$q->execute([$entity]);$newTotal=(int)array_sum($q->fetchAll(PDO::FETCH_COLUMN))-(int)$old['amount_cents'];$sign=$kind==='invoice'||$entityRow['direction']==='income'?1:-1;$gross=$kind==='invoice'?financeCents($entityRow['gross_total']):(int)$entityRow['gross_cents'];if($newTotal*$sign<0||$newTotal*$sign>$gross)throw new RuntimeException('Spätere Erstattungen zuerst prüfen.');
 $pdo->prepare('INSERT INTO finance_payments(receipt_id,invoice_id,paid_on,amount_cents,tax_cents,request_key,reversal_of,reason,admin_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$old['receipt_id'],$old['invoice_id'],$old['paid_on'],-(int)$old['amount_cents'],-(int)$old['tax_cents'],hash('sha256','reverse:'.$id),$id,$reason,$admin]);$reversalId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE finance_payments SET allocation_key=NULL WHERE id=?')->execute([$id]);if($kind==='invoice')$pdo->prepare("UPDATE invoices SET status='issued',paid_at=NULL WHERE id=? AND status='paid'")->execute([$entity]);gszAudit($pdo,$admin,'payment_reversed',['payment_id'=>$id,'reversal_id'=>$reversalId]);$pdo->commit();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeCorrectionDraft(PDO $pdo,int $admin,int $id,string $reason):int {
 if(trim($reason)===''||mb_strlen($reason)>500)throw new InvalidArgumentException('Korrekturgrund erforderlich.');$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM finance_receipts WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch();if(!$old||$old['status']!=='confirmed')throw new RuntimeException('Bestätigter Ursprungsbeleg erforderlich.');$q=$pdo->prepare('SELECT id FROM finance_receipts WHERE predecessor_id=?');$q->execute([$id]);if($exists=$q->fetchColumn()){$pdo->commit();return (int)$exists;}$q=$pdo->prepare('SELECT COALESCE(SUM(amount_cents),0) FROM finance_payments WHERE receipt_id=?');$q->execute([$id]);if((int)$q->fetchColumn()!==0)throw new RuntimeException('Zahlungszuordnungen vor Metadatenkorrektur nachvollziehbar zurücknehmen. Original bleibt erhalten.');
 $pdo->prepare('INSERT INTO finance_receipts(document_id,merchant,receipt_date,direction,gross_cents,net_cents,tax_cents,tax_rate,category,payment_method,property_id,predecessor_id,correction_reason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$old['document_id'],$old['merchant'],$old['receipt_date'],$old['direction'],$old['gross_cents'],$old['net_cents'],$old['tax_cents'],$old['tax_rate'],$old['category'],$old['payment_method'],$old['property_id'],$id,$reason]);$new=(int)$pdo->lastInsertId();gszAudit($pdo,$admin,'receipt_correction_draft',['old_id'=>$id,'new_id'=>$new]);$pdo->commit();return $new;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeSummary(PDO $pdo,string $from,string $to):array {
 if(!zgsValidDate($from)||!zgsValidDate($to)||$from>$to)throw new InvalidArgumentException('Zeitraum ungültig.');$q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN p.invoice_id IS NOT NULL OR r.direction='income' THEN p.amount_cents ELSE 0 END),0) inflow,COALESCE(SUM(CASE WHEN r.direction='expense' THEN -p.amount_cents ELSE 0 END),0) outflow,COALESCE(SUM(p.amount_cents),0) surplus,COALESCE(SUM(p.tax_cents),0) tax_balance FROM finance_payments p LEFT JOIN finance_receipts r ON r.id=p.receipt_id WHERE p.paid_on BETWEEN ? AND ?");$q->execute([$from,$to]);return $q->fetch();
}
/** Cash-flow figures are not a complete EÜR when asset payments require allocation/AfA. */
function financeAssetReview(PDO $pdo,string $from,string $to):array {
 if(!zgsValidDate($from)||!zgsValidDate($to)||$from>$to)throw new InvalidArgumentException('Zeitraum ungültig.');
 if(!(int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version='300_cash_assets'")->fetchColumn())return ['count'=>0,'net_cash_outflow_cents'=>0];
 $q=$pdo->prepare('SELECT COUNT(*) n,COALESCE(SUM(-p.amount_cents),0) amount FROM finance_payments p JOIN finance_receipts r ON r.id=p.receipt_id WHERE p.paid_on BETWEEN ? AND ? AND EXISTS(SELECT 1 FROM asset_register a WHERE a.document_id=r.document_id)');$q->execute([$from,$to]);$row=$q->fetch();return ['count'=>(int)$row['n'],'net_cash_outflow_cents'=>(int)$row['amount']];
}
